void AWeaponSystem::BeginPlay() {
    Super::BeginPlay();
    UTexture2D* Texture = StaticLoadObject(
        UTexture2D::StaticClass(),
        nullptr,
        TEXT("/Game/Textures/WeaponSkin")
    );
}

void AWeaponSystem::Tick(float DeltaTime) {
    Super::Tick(DeltaTime);
    ApplyWeaponSkin();
}
